package got.wildlife; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.entity.*; import net.minecraft.world.entity.ai.attributes.*; import net.minecraft.world.entity.ai.goal.*; import net.minecraft.world.entity.animal.Animal; import net.minecraft.world.item.ItemStack; import net.minecraft.world.item.Items; import net.minecraft.world.item.crafting.Ingredient; import net.minecraft.world.level.Level; public final class GOTFlamingoEntity extends Animal { public GOTFlamingoEntity(EntityType<? extends Animal> t,Level l){super(t,l);xpReward=2;} public static AttributeSupplier.Builder createAttributes(){return Mob.createMobAttributes().add(Attributes.MAX_HEALTH,8).add(Attributes.MOVEMENT_SPEED,.22);} protected void registerGoals(){goalSelector.addGoal(0,new FloatGoal(this));goalSelector.addGoal(1,new PanicGoal(this,1.3));goalSelector.addGoal(2,new BreedGoal(this,1));goalSelector.addGoal(3,new TemptGoal(this,1.2,Ingredient.of(Items.WHEAT_SEEDS),false));goalSelector.addGoal(4,new FollowParentGoal(this,1.2));goalSelector.addGoal(5,new WaterAvoidingRandomStrollGoal(this,1));goalSelector.addGoal(6,new LookAtPlayerGoal(this,net.minecraft.world.entity.player.Player.class,6));goalSelector.addGoal(7,new RandomLookAroundGoal(this));} public boolean isFood(ItemStack s){return s.is(Items.WHEAT_SEEDS);} public Animal getBreedOffspring(ServerLevel l,AgeableMob m){return got.GOTEntities.FLAMINGO.get().create(l);} }